<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Invoice {{ $reservation->reference }} · Stay OS</title><link rel="stylesheet" href="/assets/app.css"><script src="/assets/app.js" defer></script></head><body><div class="print-button"><button class="button primary" data-print><x-icon name="download"/>Print / Save PDF</button></div><article class="invoice"><div class="invoice-header"><div><span class="eyebrow">{{ $reservation->property->name }}</span><h1>Invoice</h1><p>{{ $reservation->property->address }}<br>{{ $reservation->property->email }}<br>{{ $reservation->property->phone }}</p></div><div><strong>{{ $reservation->reference }}</strong><p>Issued {{ $reservation->created_at->format('d F Y') }}<br>Currency: IDR<br>Status: {{ str_replace('_',' ',$reservation->status) }}</p></div></div><div class="booking-info"><div><small>Billed to</small><strong>{{ $reservation->guest_name }}</strong><p>{{ $reservation->guest_email }}</p></div><div><small>Stay dates</small><strong>{{ $reservation->check_in->format('d M Y') }} – {{ $reservation->check_out->format('d M Y') }}</strong><p>Room {{ $reservation->room->number }} · {{ $reservation->guests }} guests</p></div></div><table><thead><tr><th>Description</th><th>Nights</th><th>Rate</th><th>Amount</th></tr></thead><tbody><tr><td>{{ $reservation->room->type->name }}</td><td>{{ $reservation->check_in->diffInDays($reservation->check_out) }}</td><td>{{ number_format($reservation->nightly_rate,0,',','.') }}</td><td>{{ number_format($reservation->subtotal,0,',','.') }}</td></tr></tbody></table><div class="invoice-total"><div><span>Subtotal</span><span>Rp {{ number_format($reservation->subtotal,0,',','.') }}</span></div><div><span>Tax</span><span>Rp {{ number_format($reservation->tax,0,',','.') }}</span></div><div class="grand"><span>Total</span><span>Rp {{ number_format($reservation->total,0,',','.') }}</span></div><div><span>Paid</span><span>Rp {{ number_format($reservation->paid,0,',','.') }}</span></div><div><strong>Balance due</strong><strong>Rp {{ number_format($reservation->balance,0,',','.') }}</strong></div></div><p class="field-help">Thank you for staying with {{ $reservation->property->name }}. This is a booking invoice; local fiscal invoice requirements must be configured before production use.</p></article></body></html>
